import React, { useState } from 'react';
import '../styles/PromotionItem.css';

const PromotionItem = ({ item }) => {
    const [isFavorite, setIsFavorite] = useState(false);
    const [inCart, setInCart] = useState(false);

    const handleFavorite = () => {
        setIsFavorite(!isFavorite);
        alert(isFavorite ? 'Товар видалено з обраного' : 'Товар додано в обране!');
    };

    const handleCart = () => {
        setInCart(!inCart);
        alert(inCart ? 'Товар видалено з кошика' : 'Товар додано в кошик!');
    };

    return (
        <div className="promotion-item">
            <img src={item.img} alt={item.title} />
            <div className="promotion-item-heart" onClick={handleFavorite}>
                <img 
                    src={isFavorite ? `${process.env.PUBLIC_URL}/imgg/heart-filled.png` : `${process.env.PUBLIC_URL}/imgg/сердце.png`} 
                    alt="Додати в обране" 
                />
            </div>
            <div className="promotion-item-content">
                <div className="promotion-item-title-container">
                    <div className="promotion-item-title">{item.title}</div>
                </div>
                <div className="promotion-item-rating">
                    <div className="stars">
                        {'★'.repeat(Math.floor(item.rating))}
                        {'☆'.repeat(5 - Math.floor(item.rating))}
                    </div>
                    <div className="rating-value">{item.rating}</div>
                </div>
                <div className="promotion-item-price">
                    {item.oldPrice && <span className="old-price">{item.oldPrice}₴</span>}
                    {item.price}₴
                    {item.discount && <span className="discount">-{item.discount}%</span>}
                </div>
                <div className="promotion-item-actions">
                    <button className="promotion-item-cart-btn" onClick={handleCart}>
                        <img src={`${process.env.PUBLIC_URL}/imgg/Group 29.png`} alt="Додати в кошик" />
                    </button>
                </div>
            </div>
        </div>
    );
};

export default PromotionItem;
